test('a removed worker cannot install a baked walk returned by a retry',async()=>{
 const worker={id:'a',profile:'youngMale',status:'walking'},state={workers:[worker]},installed=[];let requests=0,finish;
 const roster=createWebGpuWorkerRoster({scene:{},residency:{},state,renderer:{backend:{isWebGPUBackend:true}},bakedWalkBank:{get(){if(++requests===1)return Promise.reject(Error('offline'));return new Promise(resolve=>{finish=resolve;});}},assetBank:{dispose(){}},pipelineAdmission:{prepare:async()=>{}},createWorker:async()=>({root:new Group(),update(){},dispose(){},async installBakedWalk(){installed.push(true);return true;}})});
 try{roster.sync();await flush();await flush();worker.status='working';roster.sync();await flush();assert.equal(requests,2);state.workers=[];roster.sync();finish({});await flush();assert.deepEqual(installed,[]);}finally{roster.dispose();}
});

test('a status change during a failed request triggers exactly one worker bake retry',async()=>{
 const entity={id:'w',profile:'youngMale',status:'walking'},state={workers:[entity]},pending=[];let requests=0,installs=0;const actor={root:new Group(),update(){},dispose(){},async installBakedWalk(){installs++;return true;}},roster=createWebGpuWorkerRoster({scene:{},residency:{},state,renderer:{backend:{isWebGPUBackend:true}},assetBank:{dispose(){}},pipelineAdmission:{prepare:async()=>{}},bakedWalkBank:{get(){requests++;return new Promise((resolve,reject)=>pending.push({resolve,reject}));}},createWorker:async()=>actor});
 try{roster.sync();await flush();await flush();assert.equal(requests,1);entity.status='working';roster.sync();pending[0].reject(Error('offline'));for(let i=0;i<4;i++)await flush();assert.equal(requests,2);pending[1].resolve({});for(let i=0;i<3;i++)await flush();assert.equal(installs,1);for(let i=0;i<4;i++)roster.sync();await flush();assert.equal(requests,2);}finally{roster.dispose();}
});

test('a selected historical worker can retry an initially unavailable bake without replacing its rig',async()=>{
 const scene=new Group(),clock=createConfirmedHistoricalClock({initialElapsed:1}),worker={id:'a',profile:'youngMale',status:'walking',x:0,z:0},state={workers:[worker]},root=new Group(),errors=[],installs=[];scene.add(root);let requests=0;
 const roster=createWebGpuWorkerRoster({scene,residency:{},state,renderer:{backend:{isWebGPUBackend:true}},bakedWalkBank:{async get(){if(++requests===1)throw Error('offline');return {};}},assetBank:{dispose(){}},pipelineAdmission:{prepare:async()=>{}},experimentalHistoricalMotion:{actorIds:['a'],clock},createWorker:async()=>({root,update(){root.visible=true;},dispose(){root.removeFromParent();},async installBakedWalk(){installs.push(true);return true;}}),onBakedWalkError:(_,error)=>errors.push(error.message)});
 try{roster.sync();for(let i=0;i<6;i++)await flush();assert.ok(errors.includes('offline'));assert.equal(requests,1);const actor=roster.get('a');assert.ok(actor);roster.sync();await flush();assert.equal(requests,1);worker.status='working';roster.sync();for(let i=0;i<3;i++)await flush();assert.equal(requests,2);assert.deepEqual(installs,[true]);assert.equal(roster.get('a'),actor);}finally{roster.dispose();clock.dispose();}
});

test('a historical worker retries its bake using the existing trajectory binding',async()=>{
 const scene=new THREE.Scene(),clock=createConfirmedHistoricalClock({initialElapsed:1}),entity={id:'w',profile:'youngMale',status:'walking',x:0,z:0},state={workers:[entity]},root=new THREE.Group(),geometry=new THREE.BoxGeometry(),material=new MeshBasicNodeMaterial(),mesh=new THREE.Mesh(geometry,material),options=[];root.add(mesh);scene.add(root);let requests=0;
 const renderer={backend:{isWebGPUBackend:true},library:{fromMaterial:m=>m.clone()}},admission={prepare:async()=>{}},actor={root,update(){root.visible=true;},dispose(){root.removeFromParent();},async installBakedWalk(_bake,value){options.push(value);return true;}},roster=createWebGpuWorkerRoster({scene,residency:{},state,renderer,assetBank:{dispose(){}},pipelineAdmission:admission,bakedWalkBank:{async get(){if(++requests===1)throw Error('offline');return {};}},experimentalHistoricalMotion:{actorIds:['w'],clock},createWorker:async()=>actor});
 try{roster.sync();for(let i=0;i<8;i++)await flush();const bound=mesh.material;assert.notEqual(bound,material);assert.equal(requests,1);entity.status='working';roster.sync();for(let i=0;i<4;i++)await flush();assert.equal(requests,2);assert.equal(options.length,1);assert.ok(options[0].motionBinding);assert.equal(options[0].motionBinding.originalMaterial(mesh),material);assert.equal(options[0].isCurrent(),true);assert.equal(roster.get('w'),actor);state.workers=[];roster.sync();assert.equal(options[0].isCurrent(),false);}finally{roster.dispose();clock.dispose();geometry.dispose();material.dispose();}
});

